<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();$flash=msp2PullFlash();$rows=[];$historial=[];$error=null;
try{$rows=$conn->query("SELECT TOP(200)* FROM (SELECT r.id_garantia,N'RECEPCION' tipo,r.id_recepcion_garantia id_origen,r.fecha_recepcion fecha,r.monto_recibido monto,a.nombre_locatario,l.cdo_local,N'Garantía recibida' concepto FROM dbo.msp_garantia_recepciones r JOIN dbo.msp_garantias g ON g.id_garantia=r.id_garantia JOIN dbo.msp_contratos_arriendo c ON c.id_contrato_arriendo=g.id_contrato_arriendo JOIN dbo.msp_arrendatarios a ON a.id_arrendatario=c.id_arrendatario JOIN dbo.msp_locales l ON l.id_local=g.id_local WHERE r.estado_recepcion=N'CONFIRMADA' UNION ALL SELECT d.id_garantia,N'DEVOLUCION',d.id_devolucion_garantia,d.fecha_devolucion,d.monto_devolucion,a.nombre_locatario,l.cdo_local,N'Devolución emitida' FROM dbo.msp_garantia_devoluciones d JOIN dbo.msp_garantias g ON g.id_garantia=d.id_garantia JOIN dbo.msp_contratos_arriendo c ON c.id_contrato_arriendo=g.id_contrato_arriendo JOIN dbo.msp_arrendatarios a ON a.id_arrendatario=c.id_arrendatario JOIN dbo.msp_locales l ON l.id_local=g.id_local WHERE d.estado_devolucion=N'EMITIDA' UNION ALL SELECT m.id_garantia,N'APLICACION',m.id_movimiento_garantia,m.fecha_movimiento,m.monto_movimiento,a.nombre_locatario,l.cdo_local,COALESCE(m.categoria_aplicacion,N'Aplicación') FROM dbo.msp_movimientos_garantia m JOIN dbo.msp_tipos_movimiento_garantia t ON t.id_tipo_movimiento_garantia=m.id_tipo_movimiento_garantia JOIN dbo.msp_garantias g ON g.id_garantia=m.id_garantia JOIN dbo.msp_contratos_arriendo c ON c.id_contrato_arriendo=g.id_contrato_arriendo JOIN dbo.msp_arrendatarios a ON a.id_arrendatario=c.id_arrendatario JOIN dbo.msp_locales l ON l.id_local=g.id_local WHERE t.codigo_movimiento=N'APLICACION_CARGO')x ORDER BY fecha DESC,id_origen DESC")->fetchAll()?:[];$historial=$conn->query('SELECT TOP(100) r.*,a.nombre_locatario,l.cdo_local FROM dbo.msp_garantia_reversas r JOIN dbo.msp_garantias g ON g.id_garantia=r.id_garantia JOIN dbo.msp_contratos_arriendo c ON c.id_contrato_arriendo=g.id_contrato_arriendo JOIN dbo.msp_arrendatarios a ON a.id_arrendatario=c.id_arrendatario JOIN dbo.msp_locales l ON l.id_local=g.id_local ORDER BY r.fecha_registro DESC')->fetchAll()?:[];}catch(Throwable $e){$error='No fue posible cargar las reversas.';}function grvMonto(mixed $v):string{return '$ '.number_format((float)$v,0,',','.');}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reversas de garantías | MSP</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css"><link rel="stylesheet" href="/portalgp/styles.css"></head><body class="gp-layout bg-light"><?php include dirname(__DIR__,2).'/templates/header.php';msp2RenderCsrfAutoFieldScript();?><main class="gp-main container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between mb-3"><div><p class="text-muted mb-1">MSP / Garantías</p><h1 class="h3">Reversas controladas</h1><p class="text-muted">Compensa errores sin borrar el movimiento original.</p></div><a class="btn btn-outline-dark btn-sm align-self-start" href="<?php echo msp2Escape(msp2Url('garantias/index.php'));?>">Volver a Garantías</a></div><?php if(is_array($flash)):?><div class="alert alert-<?php echo msp2Escape((string)($flash['type']??'info'));?>"><?php echo msp2Escape((string)($flash['message']??''));?></div><?php endif;if($error):?><div class="alert alert-danger"><?php echo $error;?></div><?php endif;?><div class="card shadow-sm"><div class="card-header fw-semibold">Operaciones reversables</div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead class="table-light"><tr><th>Fecha</th><th>Arrendatario/local</th><th>Tipo</th><th>Concepto</th><th class="text-end">Monto</th><th style="min-width:360px">Revertir</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo msp2Escape(substr((string)$r['fecha'],0,10));?></td><td><?php echo msp2Escape((string)$r['nombre_locatario']);?><div class="small text-muted">Garantía #<?php echo (int)$r['id_garantia'];?> · Local <?php echo msp2Escape((string)$r['cdo_local']);?></div></td><td><?php echo msp2Escape((string)$r['tipo']);?></td><td><?php echo msp2Escape((string)$r['concepto']);?></td><td class="text-end"><?php echo grvMonto($r['monto']);?></td><td><form method="post" action="<?php echo msp2Escape(msp2Url('garantias/revertir.php'));?>" class="d-flex gap-2"><?php msp2CsrfField();?><input type="hidden" name="tipo_origen" value="<?php echo msp2Escape((string)$r['tipo']);?>"><input type="hidden" name="id_origen" value="<?php echo (int)$r['id_origen'];?>"><input type="hidden" name="id_garantia" value="<?php echo (int)$r['id_garantia'];?>"><input name="motivo" class="form-control form-control-sm" maxlength="500" placeholder="Motivo obligatorio" required><button class="btn btn-outline-danger btn-sm" onclick="return confirm('¿Confirmas la reversa?');">Revertir</button></form></td></tr><?php endforeach;?></tbody></table></div></div><div class="card shadow-sm mt-4"><div class="card-header fw-semibold">Historial de reversas</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Fecha</th><th>Arrendatario/local</th><th>Origen</th><th class="text-end">Monto</th><th>Motivo</th></tr></thead><tbody><?php if($historial===[]):?><tr><td colspan="5" class="text-center text-muted">Sin reversas.</td></tr><?php endif;foreach($historial as $h):?><tr><td><?php echo msp2Escape(substr((string)$h['fecha_reversa'],0,10));?></td><td><?php echo msp2Escape((string)$h['nombre_locatario'].' · '.$h['cdo_local']);?></td><td><?php echo msp2Escape((string)$h['tipo_origen'].' #'.$h['id_origen']);?></td><td class="text-end"><?php echo grvMonto($h['monto_reversa']);?></td><td><?php echo msp2Escape((string)$h['motivo']);?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
